// The page's side of `@hachej/boring-ui-kit/signin`: plain fetches to the app's own sign-in routes, the person's language sent along so
// refusals come back in it. No state here; the pages and `useSignedIn` hold it.

import { signInLabels, type Lang } from './sign-in-labels';

export type { Lang };
export interface Person { readonly id: string; readonly email: string; readonly name: string; readonly role: 'owner' | 'member' }
export interface Me { readonly person: Person; readonly studio?: string }
export interface Options { readonly google: boolean; readonly studio: boolean; readonly app: string }
export interface Invitation { readonly email: string; readonly role: 'owner' | 'member'; readonly invitedBy: string; readonly at: string }

type Reply = { readonly message?: string; readonly url?: string; readonly redirect_uri?: string } & Record<string, unknown>;

async function call(lang: Lang, path: string, init: RequestInit & { readonly extra?: Record<string, string> } = {}): Promise<Reply> {
  const headers: Record<string, string> = { 'x-boring-lang': lang, ...(init.body ? { 'content-type': 'application/json' } : {}), ...init.extra };
  const r = await fetch(path, { ...init, credentials: 'same-origin', headers });
  const data = await r.json().catch(() => ({})) as Reply;
  if (!r.ok) throw new Error(data.message ?? signInLabels[lang].failed);
  return data;
}

export const signInClient = (lang: Lang) => ({
  options: () => call(lang, '/api/signin/options') as Promise<unknown> as Promise<Options>,
  /** Whether the one-use first-owner link is still good: the Worker answers `{ valid }`, the same for a used link and an unknown one. */
  firstOwnerValid: (token: string) => call(lang, '/api/signin/first-owner', { extra: { 'x-boring-first-owner': token } }).then(r => r.valid === true),
  /** The signed-in person, or null. */
  me: () => call(lang, '/api/signin/me').then(r => r as unknown as Me, () => null),
  signIn: (email: string, password: string) => call(lang, '/api/auth/sign-in/email', { method: 'POST', body: JSON.stringify({ email, password }) }),
  /** By invitation; `firstOwner` is the one-use link's token when the person opened that link. */
  signUp: (name: string, email: string, password: string, firstOwner?: string) =>
    call(lang, '/api/auth/sign-up/email', { method: 'POST', body: JSON.stringify({ name: name || email, email, password }), ...(firstOwner ? { extra: { 'x-boring-first-owner': firstOwner } } : {}) }),
  signOut: () => call(lang, '/api/auth/sign-out', { method: 'POST', body: '{}' }),
  google: () => call(lang, '/api/auth/sign-in/social', { method: 'POST', body: JSON.stringify({ provider: 'google', callbackURL: '/', errorCallbackURL: '/sign-in' }) }),
  /** Signed in during an assistant's authorization: resume it (to /consent, or straight back to the assistant). */
  resume: (query: string) => call(lang, '/api/auth/oauth2/continue', { method: 'POST', body: JSON.stringify({ postLogin: true, oauth_query: query }) }),
  consent: (accept: boolean, scope: string, query: string) => call(lang, '/api/auth/oauth2/consent', { method: 'POST', body: JSON.stringify({ accept, scope, oauth_query: query }) }),
  people: () => call(lang, '/api/signin/people').then(r => (r as unknown as { people: Invitation[] }).people),
  invite: (email: string, role: 'owner' | 'member') => call(lang, '/api/signin/people', { method: 'POST', body: JSON.stringify({ email, role }) }),
  uninvite: (email: string) => call(lang, `/api/signin/people?email=${encodeURIComponent(email)}`, { method: 'DELETE' }),
});

/** The signed query Better Auth put on /sign-in or /consent during an assistant's authorization, or '' on an ordinary visit. */
export const authorizationQuery = (): string =>
  (location.pathname === '/sign-in' || location.pathname === '/consent') && new URLSearchParams(location.search).has('client_id') ? location.search.slice(1) : '';

/** The one-use first-owner token, from `/sign-in?first-owner=<token>`, or ''. */
export const firstOwnerToken = (): string => new URLSearchParams(location.search).get('first-owner') ?? '';

/** Leave for the address an OAuth answer names; false when it names none. */
export const follow = (reply: Reply): boolean => { const to = reply.redirect_uri ?? reply.url; if (to) location.assign(to); return !!to; };

'use client';

import { useCallback, useEffect, useState } from 'react';
import { signInClient, type Lang, type Me } from './sign-in-client';

/** Who is signed in: `undefined` while asking, `null` when nobody (show the sign-in page), else the person, their role and, for an app's
 *  owners, the address of the app's page in Studio. `refresh` asks again (after a sign-in or a sign-out). */
export function useSignedIn(locale: Lang = 'fr'): { readonly me: Me | null | undefined; readonly refresh: () => void } {
  const [me, setMe] = useState<Me | null | undefined>(undefined);
  const refresh = useCallback(() => { void signInClient(locale).me().then(setMe); }, [locale]);
  useEffect(refresh, [refresh]);
  return { me, refresh };
}

'use client';

// The sign-in page of an app on `@hachej/boring-ui-kit/signin`: e-mail and password, Google when the app has its client, account creation by
// invitation (or by the one-use first-owner link, which the Worker confirms before the page shows the owner's sign-up). Signed in during an
// assistant's authorization, it resumes that authorization.
import { useEffect, useState } from 'react';
import type { FormEvent } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Spinner } from '@/components/ui/spinner';
import { authorizationQuery, firstOwnerToken, follow, signInClient, type Lang, type Options } from './sign-in-client';
import { signInLabels, type SignInLabels } from './sign-in-labels';

export interface SignInPageProps {
  /** Called once the person is signed in (outside an assistant's authorization, which leaves the page instead). */
  readonly onSignedIn: () => void;
  readonly locale?: Lang;
  readonly labels?: Partial<SignInLabels>;
}

/** The page's one column; `grid-cols-1` keeps a long line from widening it past the phone. Its text colour is the one the switch links inherit. */
const FRAME = 'mx-auto mt-24 grid w-full max-w-sm grid-cols-1 gap-4 px-4 text-foreground';
/** The block's full-width buttons are 48 px on a phone; the kit's own floor (`--control-min`, 44) stays for every other button. */
const TALL = 'max-md:min-h-12 pointer-coarse:min-h-12';
/** The two switch links: a `ghost` button, which takes the page's text colour (`FRAME`) where `link` takes the primary (a light primary does not read as text), underlined. */
const SWITCH = 'justify-self-center underline underline-offset-4';

/** `checking` until the Worker has said whether the first-owner link is good; `none` when the page was not opened from such a link. */
type Link = 'none' | 'checking' | 'valid' | 'refused';

export function SignInPage({ onSignedIn, locale = 'fr', labels: given }: SignInPageProps) {
  const t = { ...signInLabels[locale], ...given };
  const api = signInClient(locale);
  const token = firstOwnerToken();
  const [link, setLink] = useState<Link>(token ? 'checking' : 'none');
  const [mode, setMode] = useState<'in' | 'up'>('in');
  const [name, setName] = useState(''), [email, setEmail] = useState(''), [password, setPassword] = useState('');
  // Back from Google or from Studio with a refusal: Better Auth puts it in the address.
  const [error, setError] = useState<string | undefined>(() => {
    const params = new URLSearchParams(location.search);
    const failed = params.get('error');
    return failed ? params.get('error_description') ?? (/link|studio/i.test(failed) ? t.studioRefused : t.failed) : undefined;
  });
  const [busy, setBusy] = useState(false);
  const [options, setOptions] = useState<Options>({ google: false, studio: false, app: '' });
  useEffect(() => { void api.options().then(setOptions).catch(() => undefined); }, []); // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => { if (new URLSearchParams(location.search).has('error')) history.replaceState(null, '', location.pathname); }, []);
  // The owner's sign-up shows only once the Worker says the link is good; if it cannot answer, the page stays the ordinary sign-in.
  useEffect(() => {
    if (!token) return;
    let live = true;
    api.firstOwnerValid(token).then(ok => { if (live) { setMode(ok ? 'up' : 'in'); setLink(ok ? 'valid' : 'refused'); } }, () => { if (live) setLink('none'); });
    return () => { live = false; };
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  const owner = link === 'valid';
  const submit = async (event: FormEvent) => {
    event.preventDefault(); setBusy(true); setError(undefined);
    try {
      if (mode === 'in') await api.signIn(email, password);
      else await api.signUp(name, email, password, owner ? token : undefined);
      const query = authorizationQuery();
      if (query && follow(await api.resume(query))) return;
      if (owner) history.replaceState(null, '', '/');
      onSignedIn();
    } catch (failure) { setError((failure as Error).message || t.failed); } finally { setBusy(false); }
  };
  const withGoogle = async () => {
    setBusy(true); setError(undefined);
    try { if (!follow(await api.google())) setBusy(false); } catch (failure) { setError((failure as Error).message); setBusy(false); }
  };

  if (link === 'checking') return <main className={FRAME}>
    <div role="status" aria-busy="true" aria-label={t.working} data-testid="sign-in-first-owner-wait" className="grid place-items-center py-24">
      <Spinner aria-hidden="true" role="presentation" />
    </div>
  </main>;
  const app = options.app;
  return <main className={FRAME}>
    {link === 'refused' && <p role="alert" data-testid="sign-in-link-refused" className="m-0 text-sm text-destructive">{t.linkRefused}</p>}
    <div className="grid grid-cols-1 gap-1">
      <h1 className="m-0 text-xl font-semibold">{mode === 'in' ? t.signInTitle : t.signUpTitle}</h1>
      <p className="m-0 text-sm text-muted-foreground">{owner ? t.firstOwnerLead(app) : mode === 'in' ? t.signInLead(app) : t.signUpLead(app)}</p>
    </div>
    {options.google && !owner && <>
      <Button type="button" variant="outline" className={TALL} data-testid="sign-in-google" disabled={busy} onClick={() => void withGoogle()}>{t.google}</Button>
      <div className="flex items-center gap-3 text-xs text-muted-foreground"><span className="h-px flex-1 bg-border" />{t.or}<span className="h-px flex-1 bg-border" /></div>
    </>}
    <form className="grid grid-cols-1 gap-3" onSubmit={e => void submit(e)}>
      {mode === 'up' && <div className="grid grid-cols-1 gap-1.5">
        <Label htmlFor="sign-in-name">{t.name}</Label>
        <Input id="sign-in-name" autoComplete="name" value={name} onChange={e => setName(e.target.value)} />
      </div>}
      <div className="grid grid-cols-1 gap-1.5">
        <Label htmlFor="sign-in-email">{t.email}</Label>
        <Input id="sign-in-email" type="email" autoComplete="email" required value={email} onChange={e => setEmail(e.target.value)} />
      </div>
      <div className="grid grid-cols-1 gap-1.5">
        <Label htmlFor="sign-in-password">{t.password}</Label>
        <Input id="sign-in-password" type="password" minLength={8} required value={password} onChange={e => setPassword(e.target.value)}
          autoComplete={mode === 'in' ? 'current-password' : 'new-password'} />
      </div>
      <Button type="submit" className={TALL} data-testid="sign-in-submit" disabled={busy}>{busy ? t.working : mode === 'in' ? t.signIn : t.signUp}</Button>
      {error && <p role="alert" data-testid="sign-in-error" className="m-0 text-sm text-destructive">{error}</p>}
    </form>
    {!owner && <Button type="button" variant="ghost" className={SWITCH} data-testid="sign-in-switch" onClick={() => { setMode(mode === 'in' ? 'up' : 'in'); setError(undefined); }}>
      {mode === 'in' ? t.toSignUp : t.toSignIn}
    </Button>}
  </main>;
}

'use client';

// The « Allow » page of an assistant's sign-in to /mcp (Better Auth's OAuth provider sends the person here with a signed query).
import { useState } from 'react';
import { Button } from '@/components/ui/button';
import { authorizationQuery, follow, signInClient, type Lang } from './sign-in-client';
import { signInLabels, type SignInLabels } from './sign-in-labels';

export interface ConsentPageProps {
  /** The app's name, as the person reads it. */
  readonly appName: string;
  readonly locale?: Lang;
  readonly labels?: Partial<SignInLabels>;
}

export function ConsentPage({ appName, locale = 'fr', labels: given }: ConsentPageProps) {
  const t = { ...signInLabels[locale], ...given };
  const query = authorizationQuery();
  const scope = new URLSearchParams(query).get('scope') ?? 'openid profile email offline_access';
  const [error, setError] = useState<string>();
  const [busy, setBusy] = useState(false);
  const answer = async (accept: boolean) => {
    setBusy(true); setError(undefined);
    try { if (!follow(await signInClient(locale).consent(accept, scope, query))) setError(t.consentFailed); }
    catch (failure) { setError((failure as Error).message || t.consentFailed); } finally { setBusy(false); }
  };
  return <main className="mx-auto mt-24 grid w-full max-w-sm gap-4 px-4">
    <h1 className="m-0 text-xl font-semibold">{t.consentTitle}</h1>
    <p className="m-0 text-sm text-muted-foreground">{t.consentText(appName)}</p>
    {error && <p role="alert" className="m-0 text-sm text-destructive">{error}</p>}
    <div className="flex gap-2">
      <Button className="flex-1" disabled={busy || !query} onClick={() => void answer(true)}>{t.allow}</Button>
      <Button className="flex-1" variant="outline" disabled={busy || !query} onClick={() => void answer(false)}>{t.deny}</Button>
    </div>
  </main>;
}

'use client';

// The owner's invitation list: who may create an account in the app, and with which role. Owners only (the routes refuse anyone else).
// In an app linked to Studio, owners come from Studio: `canInviteOwners` is false there and the list holds members.
import { useEffect, useState } from 'react';
import type { FormEvent } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { NativeSelect, NativeSelectOption } from '@/components/ui/native-select';
import { signInClient, type Invitation, type Lang } from './sign-in-client';
import { signInLabels, type SignInLabels } from './sign-in-labels';

export interface PeopleListProps {
  readonly locale?: Lang;
  readonly labels?: Partial<SignInLabels>;
  /** Offer « as owner » (Studio itself, or an app not linked to Studio). */
  readonly canInviteOwners?: boolean;
}

export function PeopleList({ locale = 'fr', labels: given, canInviteOwners = false }: PeopleListProps) {
  const t = { ...signInLabels[locale], ...given };
  const api = signInClient(locale);
  const [people, setPeople] = useState<readonly Invitation[]>([]);
  const [email, setEmail] = useState('');
  const [role, setRole] = useState<'owner' | 'member'>('member');
  const [error, setError] = useState<string>();
  const load = () => { void api.people().then(setPeople, (e: Error) => setError(e.message)); };
  useEffect(load, []); // eslint-disable-line react-hooks/exhaustive-deps
  const act = async (run: () => Promise<unknown>) => { setError(undefined); try { await run(); load(); } catch (e) { setError((e as Error).message); } };
  const invite = (event: FormEvent) => { event.preventDefault(); void act(async () => { await api.invite(email, role); setEmail(''); }); };

  // Every grid is one `minmax(0, 1fr)` column (`grid-cols-1`): an implicit column grows to its widest line, so a long address would push the
  // list wider than the screen it sits in. The address truncates inside its row instead, and « Retirer » stays in view.
  return <section className="grid grid-cols-1 gap-3">
    <div className="grid grid-cols-1 gap-1">
      <h2 className="m-0 text-base font-semibold">{t.peopleTitle}</h2>
      <p className="m-0 text-sm text-muted-foreground">{t.peopleLead}</p>
    </div>
    <form className="flex flex-wrap gap-2" onSubmit={invite}>
      <Input className="min-w-0 flex-1 basis-48" type="email" required placeholder={t.email} aria-label={t.email} data-testid="people-email" value={email} onChange={e => setEmail(e.target.value)} />
      {canInviteOwners && <NativeSelect aria-label={t.peopleTitle} data-testid="people-role" value={role} onChange={e => setRole(e.target.value as 'owner' | 'member')}>
        <NativeSelectOption value="member">{t.asMember}</NativeSelectOption>
        <NativeSelectOption value="owner">{t.asOwner}</NativeSelectOption>
      </NativeSelect>}
      <Button type="submit" data-testid="people-invite">{t.invite}</Button>
    </form>
    {error && <p role="alert" data-testid="people-error" className="m-0 text-sm text-destructive">{error}</p>}
    {people.length === 0 ? <p data-testid="people-empty" className="m-0 text-sm text-muted-foreground">{t.nobody}</p> : <ul className="m-0 grid list-none grid-cols-1 gap-1 p-0">
      {people.map(p => <li key={p.email} data-testid="people-row" className="flex min-w-0 items-center gap-2 text-sm">
        <span title={p.email} className="min-w-0 flex-1 truncate">{p.email}</span>
        <span className="shrink-0 text-muted-foreground">{p.role === 'owner' ? t.owner : t.member}</span>
        <Button size="sm" variant="ghost" className="shrink-0" data-testid="people-remove" onClick={() => void act(() => api.uninvite(p.email))}>{t.remove}</Button>
      </li>)}
    </ul>}
  </section>;
}

'use client';

// The « Studio » entry of an app's left pane, for its owners only: a nav item (the shape AppShell's `nav` takes) whose screen opens the
// app's page in Studio. Studio's own session decides what happens there: straight in when signed in, Studio's sign-in otherwise.
import type { ComponentType, ReactNode } from 'react';
import { ExternalLinkIcon } from '../_shared/icons';
import { Button } from '@/components/ui/button';
import type { Lang, Me } from './sign-in-client';
import { signInLabels, type SignInLabels } from './sign-in-labels';

export interface StudioNavItem {
  readonly id: string;
  readonly label: string;
  readonly icon: ComponentType<{ className?: string }>;
  readonly render: () => ReactNode;
}

/** The entry when the signed-in person owns the app (the routes give `studio` to owners only), else nothing to add. */
export function studioNavItem(me: Me | null | undefined, locale: Lang = 'fr', given?: Partial<SignInLabels>): readonly StudioNavItem[] {
  const studio = me?.studio;
  if (!studio) return [];
  const t = { ...signInLabels[locale], ...given };
  return [{
    id: 'studio', label: t.studio, icon: ExternalLinkIcon,
    render: () => <main className="mx-auto mt-16 grid w-full max-w-sm gap-3 px-4">
      <p className="m-0 text-sm text-muted-foreground">{t.studioLead}</p>
      <Button nativeButton={false} render={<a href={studio} />}>{t.openStudio}</Button>
    </main>,
  }];
}
